local GachaponSkinBlendTreasureBoxNode = Class('GachaponSkinBlendTreasureBoxNode')
local GoodsNodePath = "Game.Behaviours.GoodNodeMB"
local IdolLive3D_Utils  = import('Game.IdolLive3D.IdolLive3D_Utils')

function GachaponSkinBlendTreasureBoxNode:__init()
	self.goodNodeEnv = nil
end

function GachaponSkinBlendTreasureBoxNode:__delete()
	self.goodNodeEnv = nil
end

function GachaponSkinBlendTreasureBoxNode:Awake()

end

function GachaponSkinBlendTreasureBoxNode:RefreshShow(data)
	self.data = data
	self.goodsId = self.data.goodsId
	local goodsType = GoodsUtils.GetIdType(self.goodsId)
	local isSkin = goodsType == Constants.IDType.CardSkin
	CfUtils.SetActive(self.GoodItem.gameObject,not isSkin)
	CfUtils.SetActive(self.SkinItem.gameObject,isSkin)
	CfUtils.SetUISwitchImage(self.ImgBgUp, isSkin and 2 or 1)
	if goodsType == Constants.IDType.CardSkin then
		self:RefreshSkinShow()
	else
		self:RefreshGoodsShow()
	end
end

function GachaponSkinBlendTreasureBoxNode:RefreshSkinShow()
	---@type CardSkinVo
	local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(self.goodsId)
	if skinVo then
		CfUtils.FillImage(self.SkinRoleHead, skinVo.cardHeadList)
		if string.isEmpty(skinVo.version) then
			CfUtils.SetActive(self.SkinBrand, false)
		else
			CfUtils.SetActive(self.SkinBrand, true)
			CfUtils.FillImage(self.SkinBrand, skinVo.version)
		end
		local cardVo = CardConfMgr:GetInstance():GetCardBySkinRefId(self.goodsId)
		-- 是否可互动
		local isInteractive = cardVo.defaultSkin ~= nil and IdolLive3D_Utils.GetLive3DCardVoRow(cardVo.defaultSkin)
		CfUtils.SetActive(self.ImgInteract, isInteractive)
	end
	
	local skinGoodsVo = CfUtils.GetCfVo(AutoIds.IdSetting711, "SkinGoodsVo", self.goodsId)
	
	local state = skinGoodsVo.quality - 2
	CfUtils.SetUISwitchImage(self.SkinQualityFrame, state)
	
	CfUtils.PlayAnimation(self.UIFX_Quality,string.format("GachaponSkinBlendTreasureboxNode_Quality_%s",state))
	CfUtils.SetActive(self.ImgFragMent.gameObject,false)
	CfUtils.SetActive(self.ImgNew.gameObject,true)
	
	if isSet(self.data,"convertGoods") then
		CfUtils.SetActive(self.ImgFragMent.gameObject,true)
		CfUtils.SetActive(self.ImgNew.gameObject,false)
		local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.data.convertGoods.goodsId)
		if vo then
			CfUtils.FillImage(self.SkinGoodIcon,vo.photoPath)
			CfUtils.FillText(self.SkinNum,self.data.convertGoods.num)
		end
	end
	
end

function GachaponSkinBlendTreasureBoxNode:RefreshGoodsShow()
	local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.goodsId)
	if isNotNull(vo) then
		if isNull(self.goodNodeEnv) then
			local env = CfUtils.GetLuaScr(self.GoodNode, GoodsNodePath)
			if isNotNull(env) then
				self.goodNodeEnv = env
			end
		end
		self.goodNodeEnv:Reload(
				{
					goodsId = self.goodsId,
					text = "x" .. self.data.num,
					isShowNo = true
				}
		)
		self.goodNodeEnv:SetClickButtonAction(function(goodsId)
			local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
			if isTable(goodsVo) then
				GameUtils.ShowCommonTipsBoard(self.goodNodeEnv.controller.gameObject, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
			end
		end)
		local state = vo.quality - 2
		CfUtils.SetUISwitchImage(self.GoodQuality,state)
		CfUtils.SetUISwitchImage(self.GoodQualityFrame,state)
		CfUtils.PlayAnimation(self.UIFX_Quality,string.format("GachaponSkinBlendTreasureboxNode_Quality_%s",state))
		self.goodNodeEnv:SetIconAlpha(1)
	end
end

---播放反面动画
function GachaponSkinBlendTreasureBoxNode:PlayBackAni()
	CfUtils.PlayAnimation(self.controller,"GachaponSkinBlendTreasureboxNode_Back")
end

