function GachaponSkinBlendTreasureBoxNode:PlayBackToFrontAni()
	CfUtils.PlayAnimation(self.controller,"GachaponSkinBlendTreasureboxNode_BackToFront")
end

function GachaponSkinBlendTreasureBoxNode:PlayFrontAni()
	CfUtils.PlayAnimation(self.controller,"GachaponSkinBlendTreasureboxNode_Front")
end

function GachaponSkinBlendTreasureBoxNode:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return GachaponSkinBlendTreasureBoxNode